<?php
$file=__DIR__.'/inventory.json';$items=file_exists($file)?json_decode(file_get_contents($file),true):[['id'=>1,'name'=>'Desk Lamp','stock'=>12,'price'=>185000],['id'=>2,'name'=>'Office Chair','stock'=>7,'price'=>850000]];
if($_SERVER['REQUEST_METHOD']==='POST'){$items[]=['id'=>count($items)+1,'name'=>trim($_POST['name']),'stock'=>(int)$_POST['stock'],'price'=>(float)$_POST['price']];file_put_contents($file,json_encode($items,JSON_PRETTY_PRINT));header('Location: '.$_SERVER['PHP_SELF']);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><title>Inventory</title></head><body class="bg-dark text-light"><main class="container py-5"><h1>Inventory System</h1><form method="post" class="row g-2 my-4"><input class="form-control col" name="name" placeholder="Product" required><input class="form-control col" name="stock" type="number" placeholder="Stock" required><input class="form-control col" name="price" type="number" placeholder="Price" required><button class="btn btn-info">Add</button></form><table class="table table-dark table-hover"><tr><th>ID</th><th>Product</th><th>Stock</th><th>Price</th></tr><?php foreach($items as $x):?><tr><td><?=$x['id']?></td><td><?=htmlspecialchars($x['name'])?></td><td><?=$x['stock']?></td><td>Rp<?=number_format($x['price'],0,',','.')?></td></tr><?php endforeach;?></table></main></body></html>